pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Convert N to usize for indexing
    let n = N as usize;
    // Sanity check: a and b must both have length N
    assert_eq!(a.len(), n, "Array `a` must have length N");
    assert_eq!(b.len(), n, "Array `b` must have length N");

    let mut sum: i32 = 0;
    for i in 0..n {
        // According to the problem, b[i] is either i or i+1.
        // If b[i] == i, we write 1; otherwise (i+1) we write 2.
        let v = if b[i] == i as i32 { 1 } else { 2 };
        a[i] = v;
        sum += v;
    }
    sum
}

